/* eslint-disable no-console */
import { ISerialisedError } from '@game-studio/exceptions';
import { IProvider } from '../types';

export class ConsoleProvider implements IProvider {
    public logsToServer = false;
    private locale: string;
    private operator: string;

    public setLocale(locale: string) {
        this.locale = locale;
    }

    public setOperator(operator: string) {
        this.operator = operator;
    }

    public error(error: ISerialisedError): void {
        const styles = 'color: red; font-weight: bold;';

        console.groupCollapsed(`%c🔥ERROR (${this.locale} - ${this.operator}) - ${error.name}`, styles);
        console.log('%c🤜MESSAGE', styles, error.message);
        console.log('%c🤜STACK', styles, error.stack);
        console.log('%c🤜DATA', styles, error.data || {});
        console.groupEnd();
    }

    public warn<T>(name: string, message: string, data?: T) {
        this.printMessage(`🚧WARN (${this.locale} - ${this.operator})`, name, message, 'orange', data);
    }

    public info<T>(name: string, message: string, data?: T) {
        this.printMessage(`📡INFO (${this.locale} - ${this.operator})`, name, message, 'blue', data);
    }

    public debug<T>(name: string, message: string, data?: T): void {
        this.printMessage(`🔋DEBUG (${this.locale} - ${this.operator})`, name, message, 'blue', data);
    }

    private printMessage<T>(logLevel: string, name: string, message: string, fontColour: string, data?: T) {
        const styles = `color: ${fontColour}; font-weight: bold;`;

        if (data !== undefined) {
            console.groupCollapsed(`%c${logLevel} - ${name}: ${message}`, styles);
            console.log('%c🤜DATA', styles, data);
            console.groupEnd();
        } else {
            console.log(`%c${logLevel} - ${name}: ${message}`, styles);
        }
    }

    public startSchedule() {
        // do nothing
    }

    public cancelSchedule() {
        // do nothing
    }
}
